-- ====================================================================================================
-- 2026-10-31: order every word's meanings by how often WordNet says they are used.
--
-- THE PROBLEM
--   meaning.rank is meant to be "1 = most common sense", but across parts of speech it only followed the
--   order of the original dictionary. The noun "phone" (13 uses) was rank 2 behind the verb (7 uses); the verb
--   "use" (603 uses) was rank 3 behind the noun (90). Onboarding seeds rank 1 as "already known", so the
--   common sense showed up as a "new meaning" in the article sidebar. The popularity score and the
--   "key meaning (rank <= 2)" rule read the same order.
--
-- WHAT IT DOES
--   * STEP 1  adds meaning.use_count (WordNet's SemCor usage count for that word in that sense).
--   * STEP 2  fills use_count by (term, WordNet sense id), then re-numbers rank 1..n by use_count
--             (highest first, the old rank breaks ties) for every word with 2+ meanings that ALL have a
--             count. A word with any uncounted meaning (no WordNet id, e.g. function words) keeps its
--             rank untouched. Nothing is added or deleted; no reader, article or quiz row changes.
--   * STEP 3  (optional) gives each reader the new rank-1 meaning of the words they were onboarding-seeded
--             on, so a changed rank 1 does not turn into a "new meaning" for them.
--   On the 2026-10-31 copy of prod: 20,946 of 21,792 meanings get a count; about 5,500 words are eligible;
--   1,104 of them change order and 790 get a different rank 1.
--
-- Source of the counts: LanJourney-lib/scripts/assign_sense_use_count.py (43341 (term, sense, count) rows below).
-- This file is ~1 MB: run it with psql (the Supabase SQL editor is too small for it):
--     psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f updates/2026-10-31_sense_order_by_use.sql
-- There is no staging (decided 2026-10-23), so this runs on prod.
--
-- HOW TO RUN
--   1. STEP 1 runs as part of the file (it only adds a nullable column; safe to repeat).
--   2. STEP 2 is ONE statement (a DO block), all-or-nothing. As shipped it is a DRY RUN: it does everything,
--      then deliberately fails with a message that starts "DRY RUN OK" and lists the numbers -- the failure
--      rolls everything back. Anything else in the message means STOP and send it to me.
--   3. If the numbers look right, change  dry_run CONSTANT BOOLEAN := TRUE  to  FALSE  and run it again.
--   4. Run the VERIFY queries at the bottom. Run STEP 3 only if you want it (it has its own preview).
-- A copy of every meaning's old rank is kept in meaning_rank_backup_20261031 (see RESTORE at the bottom).
-- ====================================================================================================


-- ----------------------------------------------------------------------------------------------------
-- STEP 1: the column
-- ----------------------------------------------------------------------------------------------------
ALTER TABLE meaning ADD COLUMN IF NOT EXISTS use_count INTEGER;
COMMENT ON COLUMN meaning.use_count IS
  'WordNet (SemCor) count of how often this word is used in this sense; NULL when unknown. rank is derived from it.';


-- ----------------------------------------------------------------------------------------------------
-- STEP 2: fill use_count and re-number rank
-- ----------------------------------------------------------------------------------------------------
DO $body$
DECLARE
  dry_run CONSTANT BOOLEAN := TRUE;   -- <<< change to FALSE to apply for real
  rows_loaded INT; before_n INT; after_n INT; with_id INT; counted INT;
  words_eligible INT; words_reordered INT; top_changed INT; bad INT;
BEGIN
  CREATE TEMP TABLE _c (term TEXT, sense TEXT, uses INT) ON COMMIT DROP;
  INSERT INTO _c
  SELECT split_part(l, '|', 1), split_part(l, '|', 2), split_part(l, '|', 3)::INT
  FROM regexp_split_to_table($counts$
