$counts$, E'\n') AS l
  WHERE l <> '';

  SELECT count(*) INTO rows_loaded FROM _c;
  IF rows_loaded <> 43341 THEN
    RAISE EXCEPTION 'loaded % count rows, expected 43341 -- aborting, nothing changed', rows_loaded;
  END IF;

  SELECT count(*) INTO before_n FROM meaning;

  UPDATE meaning m SET use_count = c.uses
  FROM _c c JOIN vocabulary v ON LOWER(v.term) = c.term
  WHERE m.vocab_id = v.id AND m.wordnet_sense_id = c.sense;

  SELECT count(*) FILTER (WHERE wordnet_sense_id IS NOT NULL), count(*) FILTER (WHERE use_count IS NOT NULL)
  INTO with_id, counted FROM meaning;
  IF counted < with_id * 0.98 THEN
    RAISE EXCEPTION 'only % of % meanings with a WordNet id got a count -- aborting, nothing changed (is this the right database?)',
      counted, with_id;
  END IF;

  -- Built-in backup of the old order: every meaning's rank, exactly as it is right now.
  CREATE TABLE IF NOT EXISTS meaning_rank_backup_20261031 AS SELECT id, vocab_id, rank FROM meaning;
  ALTER TABLE meaning_rank_backup_20261031 ENABLE ROW LEVEL SECURITY;  -- keep it off the public API

  -- New order, only for words with 2+ meanings that ALL have a count.
  CREATE TEMP TABLE _r ON COMMIT DROP AS
  SELECT m.id, m.vocab_id, m.rank AS old_rank,
         ROW_NUMBER() OVER (PARTITION BY m.vocab_id ORDER BY m.use_count DESC, m.rank, m.id) AS new_rank
  FROM meaning m
  WHERE m.vocab_id IN (SELECT vocab_id FROM meaning GROUP BY vocab_id
                       HAVING count(*) >= 2 AND count(use_count) = count(*));

  SELECT count(DISTINCT vocab_id), count(DISTINCT vocab_id) FILTER (WHERE old_rank <> new_rank),
         count(*) FILTER (WHERE new_rank = 1 AND old_rank <> 1)
  INTO words_eligible, words_reordered, top_changed FROM _r;

  UPDATE meaning m SET rank = r.new_rank FROM _r r WHERE m.id = r.id AND m.rank <> r.new_rank;

  -- Checks: nothing added or lost, ranks are 1..n without gaps, and rank 1 really has the highest count.
  SELECT count(*) INTO after_n FROM meaning;
  IF after_n <> before_n THEN
    RAISE EXCEPTION 'meaning count changed % -> % -- aborting, nothing changed', before_n, after_n;
  END IF;

  SELECT count(*) INTO bad FROM (
    SELECT vocab_id FROM meaning WHERE vocab_id IN (SELECT vocab_id FROM _r)
    GROUP BY vocab_id HAVING min(rank) <> 1 OR max(rank) <> count(*) OR count(DISTINCT rank) <> count(*)) x;
  IF bad > 0 THEN
    RAISE EXCEPTION '% re-ranked words do not have ranks 1..n -- aborting, nothing changed', bad;
  END IF;

  SELECT count(*) INTO bad FROM meaning m
  WHERE m.rank = 1 AND m.vocab_id IN (SELECT vocab_id FROM _r)
    AND m.use_count < (SELECT max(x.use_count) FROM meaning x WHERE x.vocab_id = m.vocab_id);
  IF bad > 0 THEN
    RAISE EXCEPTION '% words still have a rank 1 that is not the most used -- aborting, nothing changed', bad;
  END IF;

  IF dry_run THEN
    RAISE EXCEPTION 'DRY RUN OK (this error is expected; nothing was saved): meanings with a count % of % with a WordNet id (% total), words re-ranked %, words whose order changed %, words with a different rank 1 %',
      counted, with_id, after_n, words_eligible, words_reordered, top_changed;
  END IF;
END
$body$;


-- ----------------------------------------------------------------------------------------------------
-- VERIFY after a real run (run each separately)
-- ----------------------------------------------------------------------------------------------------
-- 1. Expect 0: re-ranked words whose rank 1 is not the most used.
--    SELECT count(*) FROM meaning m
--    WHERE m.rank = 1 AND m.use_count < (SELECT max(x.use_count) FROM meaning x WHERE x.vocab_id = m.vocab_id)
--      AND NOT EXISTS (SELECT 1 FROM meaning y WHERE y.vocab_id = m.vocab_id AND y.use_count IS NULL);
-- 2. Spot check: phone -> noun first, use -> verb first, open -> verb first, work -> noun first, good -> adjective first.
